// Checks for pr581_sbml_minimal_fixes.graphql (field names generated by biocypher PR #581)
// [description, GraphQL query, function counting items in the result, Cypher count query]
export const checks = [
  ["models", "{ models { id name } }", (d) => d.models.length,
   "MATCH (n:Model) RETURN count(n)"],
  ["species (PhysicalEntityRepresentation)", "{ physicalEntityRepresentations { id name } }",
   (d) => d.physicalEntityRepresentations.length,
   "MATCH (n:PhysicalEntityRepresentation) WHERE NOT n:PhysicalCompartment RETURN count(n)"],
  ["reactions (Process)", "{ processes { id name } }", (d) => d.processes.length,
   "MATCH (n:Process) RETURN count(n)"],
  ["species -> reaction (Reactant)", "{ physicalEntityRepresentations { reactant { id } } }",
   (d) => d.physicalEntityRepresentations.flatMap((n) => n.reactant).length,
   "MATCH ()-[r:Reactant]->() RETURN count(r)"],
  ["species -> reaction (Modifier)", "{ physicalEntityRepresentations { modifier { id } } }",
   (d) => d.physicalEntityRepresentations.flatMap((n) => n.modifier).length,
   "MATCH ()-[r:Modifier]->() RETURN count(r)"],
  ["reaction -> species (Product)", "{ processes { product { id } } }",
   (d) => d.processes.flatMap((n) => n.product).length,
   "MATCH ()-[r:Product]->() RETURN count(r)"],
  ["species -> compartment (ContainedEntity)", "{ physicalEntityRepresentations { containedentity { id } } }",
   (d) => d.physicalEntityRepresentations.flatMap((n) => n.containedentity).length,
   "MATCH ()-[r:ContainedEntity]->() RETURN count(r)"],
  ["species -> model (IsEntityOf)", "{ physicalEntityRepresentations { isentityof { id } } }",
   (d) => d.physicalEntityRepresentations.flatMap((n) => n.isentityof).length,
   "MATCH ()-[r:IsEntityOf]->() RETURN count(r)"],
  ["list property (is)", "{ physicalEntityRepresentations(where: { id: { eq: \"PX\" } }) { id is } }",
   (d) => d.physicalEntityRepresentations.length,
   "MATCH (n:PhysicalEntityRepresentation {id: 'PX'}) RETURN count(n)"],
];
